mapper.sql:
WHERE s.`adjustflag` = #{adjustFlag}

    AND s.`trade_date` = #{tradeDate}
    AND s.`trade_date` = (SELECT MAX(x.`trade_date`) FROM `stock_score_daily` x WHERE x.`adjustflag` = #{adjustFlag})

AND (s.`code` LIKE CONCAT('%',#{keyword},'%') OR i.`name` LIKE CONCAT('%',#{keyword},'%'))
AND s.`total_score` >= #{minScore}
AND i.`market` = #{market}
AND i.`industry` = #{industry}
